contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool callFailed;
        try c.transfer(from, caddress, _tos, v) returns (bool ok) {
            callFailed = !ok;
        } catch {
            callFailed = true;
        }

        // General rule: success (callFailed == false) implies every inner call succeeded;
        // failure implies C.transfer reverted or returned false rather than normal success.
        // Since success requires all inner transferFrom calls to return true, and failure
        // propagates as a revert, observing normal success is the only way to get true.
        assert(!callFailed);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address caddress, address[] memory _tos, uint[] memory v) public payable {
        require(_tos.length > 0);
        require(_tos.length == v.length);

        bool reverted;
        bool returned;
        bool ok;

        try c.transfer(from, caddress, _tos, v) returns (bool _ok) {
            ok = _ok;
            returned = true;
            reverted = false;
        } catch {
            reverted = true;
            returned = false;
        }

        // P must never report success because the inner call to caddress
        // cannot possibly succeed as an ERC-20 transferFrom in the test environment.
        assert(!(returned && ok));
    }

    receive() external payable {}
}

